package com.fream.back.domain.notification.service.kafka;

import com.fream.back.domain.faq.entity.Faq;
import com.fream.back.domain.faq.repository.FaqRepository;
import com.fream.back.domain.notification.dto.kafka.NotificationEvent;
import com.fream.back.domain.notification.entity.Notification;
import com.fream.back.domain.notification.exception.NotificationException;
import com.fream.back.domain.notification.repository.NotificationRepository;
import com.fream.back.domain.notification.service.command.NotificationCommandService;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.service.query.ProductQueryService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.support.Acknowledgment;
import org.springframework.kafka.support.KafkaHeaders;
import org.springframework.messaging.handler.annotation.Header;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Duration;
import java.time.Instant;
import java.util.Optional;





@Service
@RequiredArgsConstructor
@Slf4j
public class NotificationEventConsumer {

    private final NotificationCommandService paymentCommandService;
    private final NotificationEventProducer paymentEventProducer;
    private final FaqRepository orderRepository;
    private final NotificationRepository paymentRepository;
    private final ProductQueryService userQueryService;





    @KafkaListener(
            topics = "payment-processing-topic",
            groupId = "payment-processing-group",
            containerFactory = "paymentEventKafkaListenerContainerFactory"
    )
    @Transactional
    public void handlePaymentEvent(
            @Payload NotificationEvent event,
            @Header(KafkaHeaders.RECEIVED_PARTITION) int partition,
            @Header(KafkaHeaders.OFFSET) long offset,
            Acknowledgment acknowledgment) {

        Instant start = Instant.now();

        try {
            log.info("결제 처리 이벤트 수신: 주문ID={}, 이벤트ID={}, 파티션={}, 오프셋={}",
                    event.getOrderId(), event.getEventId(), partition, offset);


            if (isPaymentAlreadyProcessed(event.getOrderId())) {
                log.warn("이미 처리된 결제 요청 - 중복 처리 방지: 주문ID={}", event.getOrderId());
                acknowledgment.acknowledge();
                return;
            }


            Faq order = orderRepository.findById(event.getOrderId())
                    .orElseThrow(() -> new IllegalArgumentException(
                            "주문을 찾을 수 없습니다. 주문ID: " + event.getOrderId()));


            Product user = userQueryService.findByEmail(event.getUserEmail());


            if (!order.getUser().getId().equals(user.getId())) {
                log.error("주문과 사용자 정보 불일치: 주문ID={}, 주문사용자ID={}, 요청사용자ID={}",
                        event.getOrderId(), order.getUser().getId(), user.getId());
                throw new NotificationException(null, "주문과 사용자 정보가 일치하지 않습니다.");
            }


            Notification payment = paymentCommandService.processPayment(order, user, event.getPaymentRequest());

            log.info("결제 처리 완료: 주문ID={}, 결제ID={}, 결제상태={}",
                    event.getOrderId(), payment.getId(), payment.getStatus());


            acknowledgment.acknowledge();


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.info("결제 처리 완료 - 소요시간: {}ms, 주문ID={}", duration.toMillis(), event.getOrderId());

        } catch (NotificationException e) {
            log.error("결제 처리 실패 (NotificationException): 주문ID={}, 오류={}",
                    event.getOrderId(), e.getMessage(), e);
            handlePaymentFailure(event, e, acknowledgment);

        } catch (Exception e) {
            log.error("결제 처리 중 예상치 못한 오류: 주문ID={}, 오류={}",
                    event.getOrderId(), e.getMessage(), e);
            handlePaymentFailure(event, e, acknowledgment);
        }
    }




    @KafkaListener(
            topics = "payment-retry-topic",
            groupId = "payment-retry-group",
            containerFactory = "paymentEventKafkaListenerContainerFactory"
    )
    @Transactional
    public void handlePaymentRetryEvent(
            @Payload NotificationEvent event,
            Acknowledgment acknowledgment) {

        try {
            log.info("결제 재시도 처리: 주문ID={}, 재시도횟수={}",
                    event.getOrderId(), event.getRetryCount());


            if (event.isMaxRetryExceeded()) {
                log.error("최대 재시도 횟수 초과: 주문ID={}, 재시도횟수={}",
                        event.getOrderId(), event.getRetryCount());
                acknowledgment.acknowledge();
                return;
            }


            if (isPaymentAlreadyProcessed(event.getOrderId())) {
                log.info("재시도 중 결제 완료 확인: 주문ID={}", event.getOrderId());
                acknowledgment.acknowledge();
                return;
            }


            Thread.sleep(Math.min(1000 * event.getRetryCount(), 5000));


            handlePaymentEvent(event, 0, 0, acknowledgment);

        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            log.error("결제 재시도 중 인터럽트 발생: 주문ID={}", event.getOrderId());
            acknowledgment.acknowledge();
        } catch (Exception e) {
            log.error("결제 재시도 처리 중 오류: 주문ID={}, 오류={}",
                    event.getOrderId(), e.getMessage(), e);
            acknowledgment.acknowledge();
        }
    }




    private boolean isPaymentAlreadyProcessed(Long orderId) {
        try {
            Optional<Notification> existingPayment = paymentRepository.findByOrder_Id(orderId);

            if (existingPayment.isPresent()) {
                Notification payment = existingPayment.get();
                log.info("기존 결제 발견: 주문ID={}, 결제ID={}, 결제상태={}",
                        orderId, payment.getId(), payment.getStatus());


                return payment.isSuccess();
            }

            return false;
        } catch (Exception e) {
            log.error("결제 중복 검사 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
            return false;
        }
    }




    private void handlePaymentFailure(NotificationEvent event, Exception error, Acknowledgment acknowledgment) {
        try {

            if (isRetryableError(error)) {
                log.info("재시도 가능한 오류로 재시도 이벤트 발행: 주문ID={}", event.getOrderId());
                paymentEventProducer.sendPaymentRetryEvent(event);
            } else {
                log.error("재시도 불가능한 오류로 결제 실패 처리: 주문ID={}, 오류={}",
                        event.getOrderId(), error.getMessage());

            }

            acknowledgment.acknowledge();

        } catch (Exception e) {
            log.error("결제 실패 처리 중 오류: 주문ID={}, 오류={}", event.getOrderId(), e.getMessage(), e);
            acknowledgment.acknowledge();
        }
    }




    private boolean isRetryableError(Exception error) {

        return !(error instanceof IllegalArgumentException) &&
                !(error.getMessage() != null && error.getMessage().contains("찾을 수 없습니다"));
    }
}

