    private void handleRefundIfNecessary(Notification payment) {
        Instant start = Instant.now();
        try {
            if (payment.getImpUid() == null || payment.getImpUid().isBlank()) {
                log.warn("환불 처리 불가: 결제ID={}, 결제식별자(impUid)가 없습니다.", payment.getId());
                return;
            }

            log.info("결제 환불 처리 시작: 결제ID={}, impUid={}", payment.getId(), payment.getImpUid());

            boolean refundSuccess = portOneApiClient.cancelPayment(payment.getImpUid());

            if (refundSuccess) {
                payment.updateStatus(NotificationStatus.REFUNDED);
                paymentRepository.save(payment);
                log.info("결제 환불 처리 완료: 결제ID={}, 상태=REFUNDED", payment.getId());
            } else {
                log.error("결제 환불 처리 실패: 결제ID={}", payment.getId());
                throw new NotificationException(NotificationErrorCode.PAYMENT_CANCELLATION_FAILED,
                        "환불 요청이 실패했습니다. 관리자에게 문의하세요.");
            }


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("결제 환불 처리 시간: {}ms", duration.toMillis());
        } catch (NotificationException e) {
            throw e;
        } catch (Exception e) {
            log.error("결제 환불 처리 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
                    payment.getId(), e.getMessage(), e);
            throw new NotificationException(NotificationErrorCode.PAYMENT_CANCELLATION_FAILED,
                    "환불 처리 중 오류가 발생했습니다: " + e.getMessage());
        }
    }







    private void notifyUsersAndUpdateSaleStatus(Faq order, Notification payment) {
        try {
            log.info("결제 관련 알림 및 판매 상태 업데이트 시작: 주문ID={}", order.getId());


            FaqBid orderBid = order.getOrderBid();
            if (orderBid == null) {

                StyleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
                if (saleBid == null) {
                    log.warn("주문에 연결된 판매 입찰 정보가 없습니다: 주문ID={}", order.getId());
                    return;
                }

                Style sale = saleBid.getSale();
                if (sale == null) {
                    log.warn("판매 입찰에 연결된 판매 정보가 없습니다: 판매입찰ID={}", saleBid.getId());
                    return;
                }

                sendNotifications(order, sale);
                sale.updateStatus(StyleStatus.SOLD);
                log.info("판매 상태 업데이트 완료: 판매ID={}, 상태=SOLD", sale.getId());
                return;
            }


            Style sale = orderBid.getSale();
            if (sale == null) {
                log.warn("주문 입찰에 연결된 판매 정보가 없습니다: 주문입찰ID={}", orderBid.getId());
                return;
            }

            sendNotifications(order, sale);


            sale.updateStatus(StyleStatus.SOLD);
            log.info("판매 상태 업데이트 완료: 판매ID={}, 상태=SOLD", sale.getId());
        } catch (Exception e) {

            log.error("결제 관련 알림 및 판매 상태 업데이트 중 오류 발생: 주문ID={}, 오류={}",
                    order.getId(), e.getMessage(), e);
        }
    }







    private void sendNotifications(Faq order, Style sale) {
        try {
            Product buyer = order.getUser();
            if (buyer != null) {
                notificationCommandService.createNotification(
                        buyer.getId(),
                        PaymentCategory.SHOPPING,
                        PaymentType.BID,
                        "결제가 완료되었습니다. 주문 ID: " + order.getId()
                );
                log.debug("구매자 알림 전송 완료: 구매자ID={}", buyer.getId());
            }

            Product seller = sale.getSeller();
            if (seller != null) {
                notificationCommandService.createNotification(
                        seller.getId(),
                        PaymentCategory.SHOPPING,
                        PaymentType.BID,
                        "구매자가 결제를 완료하였습니다. 판매 ID: " + sale.getId()
                );
                log.debug("판매자 알림 전송 완료: 판매자ID={}", seller.getId());
            }
        } catch (Exception e) {

            log.warn("결제 완료 알림 전송 중 오류 발생: 주문ID={}, 판매ID={}, 오류={}",
                    order.getId(), sale.getId(), e.getMessage());
        }
    }







    private void validateBank(String bankName) {
        try {
            if (bankName == null || bankName.isBlank()) {
                throw new NotificationException(NotificationErrorCode.INVALID_BANK_INFO, "은행 이름은 필수입니다.");
            }

            try {
                Bank.valueOf(bankName.toUpperCase());
            } catch (IllegalArgumentException e) {
                throw new NotificationException(NotificationErrorCode.INVALID_BANK_INFO,
                        "지원하지 않는 은행입니다: " + bankName);
            }
        } catch (NotificationException e) {
            throw e;
        } catch (Exception e) {
            throw new NotificationException(NotificationErrorCode.INVALID_BANK_INFO,
                    "은행 정보 검증 중 오류가 발생했습니다.", e);
        }
    }








    @Transactional
    public void updatePaymentStatus(Notification payment, NotificationStatus newStatus) {
        Instant start = Instant.now();
        try {
            if (payment == null) {
                throw new NotificationNotFoundException("결제 정보가 없습니다.");
            }

            if (!payment.getStatus().canTransitionTo(newStatus)) {
                throw new NotificationException(NotificationErrorCode.INVALID_PAYMENT_STATUS,
                        "현재 상태(" + payment.getStatus() + ")에서 " + newStatus + " 상태로 변경할 수 없습니다.");
            }

            log.info("결제 상태 변경: 결제ID={}, 현재상태={}, 새상태={}",
                    payment.getId(), payment.getStatus(), newStatus);

            payment.updateStatus(newStatus);
            paymentRepository.save(payment);

            log.info("결제 상태 변경 완료: 결제ID={}, 상태={}", payment.getId(), newStatus);


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("결제 상태 변경 처리 시간: {}ms", duration.toMillis());
        } catch (NotificationException e) {
            log.error("결제 상태 변경 실패: 결제ID={}, 에러코드={}, 메시지={}",
                    payment != null ? payment.getId() : "null",
                    e.getErrorCode().getCode(), e.getMessage());
            throw e;
        } catch (Exception e) {
            log.error("결제 상태 변경 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
                    payment != null ? payment.getId() : "null", e.getMessage(), e);
            throw new NotificationException(NotificationErrorCode.PAYMENT_UPDATE_FAILED,
                    "결제 상태 변경 중 오류가 발생했습니다.", e);
        }
    }








    @Transactional
    public String refundPayment(Long paymentId) {
        Instant start = Instant.now();
        try {
            log.info("결제 환불 요청 시작: 결제ID={}", paymentId);


            Notification payment = paymentRepository.findById(paymentId)
                    .orElseThrow(() -> new NotificationNotFoundException("결제 ID: " + paymentId + "를 찾을 수 없습니다."));


            if (!payment.getStatus().canTransitionTo(NotificationStatus.REFUND_REQUESTED)) {
                throw new NotificationException(NotificationErrorCode.INVALID_PAYMENT_STATUS,
                        "현재 상태에서 환불 요청을 진행할 수 없습니다. 현재 상태: " + payment.getStatus());
            }


            if (payment.getImpUid() == null || payment.getImpUid().isBlank()) {
                throw new NotificationException(NotificationErrorCode.PAYMENT_CANCELLATION_FAILED,
                        "환불 가능한 결제 ID가 없습니다.");
            }

            boolean refundSuccess = portOneApiClient.cancelPayment(payment.getImpUid());

            if (refundSuccess) {
                payment.updateStatus(NotificationStatus.REFUNDED);
                paymentRepository.save(payment);
                log.info("결제 환불 요청 성공: 결제ID={}, 상태=REFUNDED", paymentId);


                sendRefundNotification(payment);


                Instant end = Instant.now();
                Duration duration = Duration.between(start, end);
                log.debug("결제 환불 처리 시간: {}ms", duration.toMillis());

                return "환불이 성공적으로 완료되었습니다.";
            } else {
                payment.updateStatus(NotificationStatus.REFUND_REQUESTED);
                paymentRepository.save(payment);
                log.warn("결제 환불 요청 실패: 결제ID={}, 상태=REFUND_REQUESTED", paymentId);
                return "환불 요청이 실패하였습니다. 관리자에게 문의하세요.";
            }
        } catch (NotificationException e) {
            log.error("결제 환불 요청 실패: 결제ID={}, 에러코드={}, 메시지={}",
                    paymentId, e.getErrorCode().getCode(), e.getMessage());
            throw e;
        } catch (Exception e) {
            log.error("결제 환불 요청 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
                    paymentId, e.getMessage(), e);
            throw new NotificationException(NotificationErrorCode.PAYMENT_CANCELLATION_FAILED,
                    "환불 요청 중 오류가 발생했습니다: " + e.getMessage());
        }
    }






    private void sendRefundNotification(Notification payment) {
        try {
            Product user = payment.getUser();
            if (user == null) {
                log.warn("환불 알림 발송 실패: 결제ID={}, 사용자 정보가 없습니다.", payment.getId());
                return;
            }

            Faq order = payment.getOrder();
            String orderInfo = order != null ? "주문 ID: " + order.getId() : "환불금액: " + payment.getPaidAmount() + "원";

            notificationCommandService.createNotification(
                    user.getId(),
                    PaymentCategory.SHOPPING,
                    PaymentType.REFUND,
                    "결제가 환불되었습니다. " + orderInfo
            );
            log.debug("환불 알림 전송 완료: 사용자ID={}, 결제ID={}", user.getId(), payment.getId());


            if (order != null) {
                Style sale = null;


                FaqBid orderBid = order.getOrderBid();
                if (orderBid != null) {
                    sale = orderBid.getSale();
                }

                else {
                    StyleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
                    if (saleBid != null) {
                        sale = saleBid.getSale();
                    }
                }

                if (sale != null && sale.getSeller() != null) {
                    Product seller = sale.getSeller();
                    notificationCommandService.createNotification(
                            seller.getId(),
                            PaymentCategory.SHOPPING,
                            PaymentType.REFUND,
                            "구매자의 결제가 환불되었습니다. 판매 ID: " + sale.getId()
                    );
                    log.debug("판매자 환불 알림 전송 완료: 판매자ID={}, 판매ID={}",
                            seller.getId(), sale.getId());



                }
            }
        } catch (Exception e) {

            log.warn("환불 알림 전송 중 오류 발생: 결제ID={}, 오류={}",
                    payment.getId(), e.getMessage());
        }
    }
}package com.fream.back.domain.notification.entity;

import com.fream.back.domain.faq.entity.Faq;
import com.fream.back.domain.style.entity.Style;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.global.entity.BaseTimeEntity;
import jakarta.persistence.*;
import lombok.Getter;
import lombok.NoArgsConstructor;

import java.time.LocalDateTime;

@Entity @jakarta.persistence.Table(name = "payment")
@Getter
@NoArgsConstructor
@Inheritance(strategy = InheritanceType.SINGLE_TABLE)
@DiscriminatorColumn(name = "payment_type")
public abstract class Notification extends BaseTimeEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "order_id")
    private Faq order;

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "sale_id")
    private Style sale;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id", nullable = false)
    private Product user;

    @Column(nullable = false)
    private double paidAmount;
    @Column(nullable = false)
    private boolean isSuccess = false;

    private LocalDateTime paymentDate;

    @Enumerated(EnumType.STRING)
    private NotificationStatus status = NotificationStatus.PENDING;


    public void assignOrder(Faq order) {
        this.order = order;
        this.sale = null;
    }

    public void assignSale(Style sale) {
        this.sale = sale;
        this.order = null;
    }
    public void assignUser(Product user) {
        this.user = user;
    }

    public void setPaidAmount(double paidAmount) {
        this.paidAmount = paidAmount;
        this.isSuccess = paidAmount > 0;
    }
    public void updateSuccessStatus(boolean success) {
        this.isSuccess = success;
        if (success) {
            this.paymentDate = LocalDateTime.now();
        }
    }
    public void updateStatus(NotificationStatus newStatus) {
        if (this.status.canTransitionTo(newStatus)) {
            this.status = newStatus;
        } else {
            throw new IllegalStateException("결제 상태 전환이 허용되지 않습니다: " + this.status + " -> " + newStatus);
        }
    }

    public abstract String getImpUid();
}
package com.fream.back.domain.notification.entity;

import jakarta.persistence.DiscriminatorValue;
import jakarta.persistence.Entity;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

@Entity
@Getter
@NoArgsConstructor
@DiscriminatorValue("CARD")
public class CardNotification extends Notification {

    private String cardNumber;
    private String cardPassword;
    private String cardExpiration;
    private String birthDate;
    private String cardType;
    private String impUid;
    private String receiptUrl;
    private String pgProvider;
    private String pgTid;

    @Builder
